    if i == 0:
        model += x[i] >= demands[i]
    elif i == 1:
        model += x[i] + x[i-1] >= demands[i]
    elif i == len(demands) - 1:
        model += x[i-1] >= demands[i]
    elif i == len(demands) - 2:
        model += x[i-1] + x[i] >= demands[i]
    else:
        model += x[i-1] + x[i] >= demands[i]

# Objective
model.minimize(sum(x))

# Solve and print
if model.solve():
    solution = {'x': [int(val.value()) for val in x]}
    print(json.dumps(solution, indent=4))
else:
