import cpmpy as cp
import json
import numpy as np

# Data
n_teams = 8  # Number of teams
n_weeks = n_teams - 1
n_periods = n_teams // 2

# Model definition
model = cp.Model()

# Decision Variables
# home[i, j, k] is True if team i plays at home against team j in period k
home = cp.boolvar(shape=(n_teams, n_teams, n_periods), name="home")
# away[i, j, k] is True if team i plays away against team j in period k
away = cp.boolvar(shape=(n_teams, n_teams, n_periods), name="away")

# Constraints
# Every team plays once a week
for week in range(n_weeks):
    for team in range(n_teams):
        model += cp.sum([home[team, other, week % n_periods] for other in range(n_teams)]) == 1
        model += cp.sum([away[team, other, week % n_periods] for other in range(n_teams)]) == 1

# Every team plays at most twice in the same period over the tournament
for team in range(n_teams):
    for period in range(n_periods):
        model += cp.sum([home[team, other, period] for other in range(n_teams)]) <= 2
        model += cp.sum([away[team, other, period] for other in range(n_teams)]) <= 2

# Every team plays every other team
for team1 in range(n_teams):
    for team2 in range(team1 + 1, n_teams):
        model += cp.sum([home[team1, team2, period] for period in range(n_periods)]) == 1
        model += cp.sum([away[team1, team2, period] for period in range(n_periods)]) == 1

# If team1 plays at home against team2, then team2 plays away against team1
for team1 in range(n_teams):
    for team2 in range(n_teams):
        for period in range(n_periods):
            model += home[team1, team2, period] == away[team2, team1, period]

# Solve and print
if model.solve():
    home_schedule = np.zeros((n_weeks, n_periods), dtype=int)
    away_schedule = np.zeros((n_weeks, n_periods), dtype=int)
    for week in range(n_weeks):
        for period in range(n_periods):
            for team1 in range(n_teams):
                for team2 in range(n_teams):
                    if home[team1, team2, period].value():
                        home_schedule[week, period] = team1
                        away_schedule[week, period] = team2
    solution = {'home': home_schedule.tolist(), 'away': away_schedule.tolist()}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
