import cpmpy as cp
import json
import numpy as np

# Data
n = 5

# Model definition
model = cp.Model()

# Decision Variables
x = cp.intvar(1, n*n, shape=(n, n), name="x")

# Constraints
# Each number from 1 to n*n must be used exactly once
model += cp.AllDifferent(x.flat)

# The first number is placed at position (0,0)
model += x[0, 0] == 1

# Movement Type I: If the next number in the sequence is going to be placed vertically or horizontally,
# then it must be placed exactly three squares away from the previous number
for i in range(n):
    for j in range(n):
        if i + 3 < n:
            model += cp.If(x[i, j] > 1, cp.Or([x[i+3, j] == x[i, j] + 1, cp.Not(x[i+3, j] == x[i, j] + 1)]))
        if j + 3 < n:
            model += cp.If(x[i, j] > 1, cp.Or([x[i, j+3] == x[i, j] + 1, cp.Not(x[i, j+3] == x[i, j] + 1)]))

# Movement Type II: If the next number in the sequence is going to be placed diagonally,
# then it must be placed exactly two squares away from the previous number
for i in range(n):
    for j in range(n):
        if i + 2 < n and j + 2 < n:
            model += cp.If(x[i, j] > 1, cp.Or([x[i+2, j+2] == x[i, j] + 1, cp.Not(x[i+2, j+2] == x[i, j] + 1)]))
        if i + 2 < n and j - 2 >= 0:
            model += cp.If(x[i, j] > 1, cp.Or([x[i+2, j-2] == x[i, j] + 1, cp.Not(x[i+2, j-2] == x[i, j] + 1)]))
        if i - 2 >= 0 and j + 2 < n:
            model += cp.If(x[i, j] > 1, cp.Or([x[i-2, j+2] == x[i, j] + 1, cp.Not(x[i-2, j+2] == x[i, j] + 1)]))
